sp_ListarMovimentacaoEstoque	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarMovimentacaoEstoque`(p_idEmpresa INT)\nBEGIN\n\n    SELECT \n\n        m.dthMovimentacao,\n\n        p.Nome       AS NomeProduto,\n\n        t.Nome       AS TipoMovimentacao,\n\n        m.Qtde       AS Quantidade,\n\n        m.Observacao AS Motivo,\n\n        m.usuario_id AS IdUsuario,\n\n        u.Nome       AS NomeUsuario\n\n    FROM MovimentacaoEstoque m\n\n    INNER JOIN Produto p          ON p.idProduto        = m.produto_id\n\n    INNER JOIN TipoMovimentacao t ON t.idTipoMovimentacao = m.tipoMovimentacao_id\n\n    LEFT  JOIN Usuario u          ON u.idUsuario         = m.usuario_id\n\n    WHERE m.idEmpresa = p_idEmpresa\n\n    ORDER BY m.dthMovimentacao DESC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
